from pathlib import Path
import re,json,html,markdown

root=Path(__file__).parent
base='https://raw.githubusercontent.com/EyeVisionsNL/AIS-ATIS-Bridge/e2887ef5ae14257222c41257a6d421db3f79ba01/'
pages=[('Home', 'Start here', 'marine', 'Hear the call. Find the ship.', 'Your friendly guide to marine voice, ATIS identities and AIS positions.'), ('Installation', 'Installation', 'marine', 'Welcome aboard.', 'Set up your Bridge on Raspberry Pi or Ubuntu, one step at a time.'), ('First-steps', 'First steps', 'marine', 'Your first marine signal.', 'Choose your receiver, tune a channel and start listening.'), ('Receiver-and-channels', 'Receiver & channels', 'marine', 'Give your SDR a heading.', 'Scanning, Smart Gain, squelch and your Marine channel workbook.'), ('Audio-and-recordings', 'Audio & recordings', 'marine', 'Missed that call?', 'Listen live and replay the latest four marine transmissions.'), ('ATIS-and-AIS', 'ATIS & AIS map', 'marine', 'Put a voice on the map.', 'Understand validated identities, vessel matching and automatic following.'), ('Updates', 'Updates', 'marine', 'Keep your Bridge current.', 'Stable, Beta and updates that preserve your receiver settings.'), ('Troubleshooting', 'Troubleshooting', 'marine', 'Get back to listening.', 'Practical checks for reception, audio, maps and installation.')]
def url(slug): return 'index.html' if slug=='Home' else slug.lower()+'.html'
nav=''.join(f'<a href="{url(p[0])}" DATA-{p[0]}><span>{i:02}</span> &nbsp; {html.escape(p[1])}</a>' for i,p in enumerate(pages))
search=[]
for idx,(slug,label,scene,title,subtitle) in enumerate(pages):
    source=(root/'source'/f'{slug}.md').read_text()
    source=re.sub(r'\[\[([^\]]+)\]\]',lambda m:f'[{"Android app" if m[1]=="Android companion" else m[1]}]({url(m[1].replace(" ","-"))})',source)
    source=source.replace('https://raw.githubusercontent.com/EyeVisionsNL/AIS-ATIS-Bridge/main/',base)
    source=re.sub(r'^# .+\n','',source,count=1,flags=re.M)
    md=markdown.Markdown(extensions=['tables','fenced_code','toc'])
    body=md.convert(source)
    search.append({'title':label,'url':url(slug),'text':re.sub('<[^>]+>',' ',body)})
    if idx==0:
        cards=''.join(f'<a class="card" href="{url(p[0])}"><img src="{base}ais_atis_bridge/static/marine-ship-banner.webp" alt="" loading="lazy"><div class="card-body"><span class="num">GUIDE {i:02}</span><h3>{html.escape(p[1])}</h3><p>{html.escape(p[4])}</p><span class="arrow">Open guide ↗</span></div></a>' for i,p in enumerate(pages[1:],1))
        body=f'<div class="welcome"><strong>Welcome aboard.</strong> Two receivers, one harbour full of stories. Let’s connect the voice on your radio with the vessel on your map.</div><div class="section-head"><h2>Find your next step</h2><span>07 GUIDES · ONE BRIDGE</span></div><div class="cards">{cards}</div><div class="section-head"><h2>Built around your station</h2></div><p>Start with installation and receiver setup. Then explore live listening, temporary replays and vessel matching. The dashboard guide includes the project’s own preview, with clearly labelled demonstration data.</p><a class="button" href="https://github.com/EyeVisionsNL/AIS-ATIS-Bridge/issues">Questions or ideas? Visit GitHub ↗</a>'
        main=body
    else:
        main=f'<div class="article-wrap"><article class="article">{body}</article><aside class="toc" aria-label="On this page"><strong>ON THIS PAGE</strong>{md.toc}</aside></div>'
    prev=pages[idx-1] if idx else None
    nxt=pages[idx+1] if idx+1<len(pages) else None
    pager='<div class="pager">'+(f'<a href="{url(prev[0])}">← {html.escape(prev[1])}</a>' if prev else '<span></span>')+(f'<a href="{url(nxt[0])}">{html.escape(nxt[1])} →</a>' if nxt else '<a href="index.html">Back to start ↑</a>')+'</div>'
    active=re.sub(r' DATA-([^ >]+)',lambda m:' aria-current="page"' if m[1]==slug else '',nav)
    buttons='<div class="buttons"><a class="button primary" href="installation.html">Get started →</a><a class="button" href="atis-and-ais.html">Explore the AIS map ↗</a></div>' if idx==0 else ''
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(subtitle)} AIS-ATIS Bridge documentation and practical guides."><meta name="theme-color" content="#0f172a"><title>{html.escape(label)} · AIS-ATIS Bridge Guide</title><link rel="stylesheet" href="style.css?v=20261017c"><script src="app.js?v=20261017c" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">⚓</span> <span>AIS-ATIS Bridge<small>THE FIELD GUIDE</small></span></a><div class="top-links"><a href="https://github.com/EyeVisionsNL/AIS-ATIS-Bridge">GitHub ↗</a><a href="atis-and-ais.html">AIS map guide</a><span class="pill">● &nbsp; VOICE · IDENTITY · POSITION</span><button class="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">☰</button></div></header><div class="layout"><aside class="sidebar" id="sidebar"><div class="eyebrow">STATION HANDBOOK</div><div class="search"><label for="search" class="eyebrow">Find a guide</label><input id="search" type="search" placeholder="Search gain, audio, AIS…" autocomplete="off"><div class="search-results" aria-live="polite"></div></div><nav aria-label="Guides">{active}</nav><div class="side-note">Marine voice · ATIS · AIS<br>Raspberry Pi · Ubuntu<br><br>Made for curious listeners.<br><a href="https://github.com/EyeVisionsNL/AIS-ATIS-Bridge/issues">Questions & ideas ↗</a><br><a href="https://eyevisionsnl.github.io/SDRCC/">SDRCC field guide ↗</a></div></aside><main class="content" id="main"><div class="crumb">AIS-ATIS Bridge / Documentation / {html.escape(label)}</div><section class="hero"><div class="hero-media"><img class="hero-image" src="{base}ais_atis_bridge/static/marine-ship-banner.webp" alt="AIS-ATIS Bridge {scene} panorama"><div class="radar" aria-hidden="true"><div class="sweep"></div><i></i><i></i><i></i></div></div><div class="hero-copy"><div class="eyebrow">{'WELCOME TO AIS-ATIS BRIDGE' if idx==0 else 'THE AIS-ATIS Bridge GUIDE / '+label.upper()}</div><h1>{html.escape(title)}</h1><p>{html.escape(subtitle)}</p>{buttons}</div></section>{main}{pager}<footer class="footer"><span>AIS-ATIS Bridge · Marine voice. Vessel identity. AIS position.</span><span>Guide based on Stable 0.1.13</span></footer></main></div><dialog aria-label="Enlarged screenshot"><button aria-label="Close screenshot">×</button><img alt=""></dialog></body></html>'''
    (root/url(slug)).write_text(doc)
(root/'search.json').write_text(json.dumps(search,ensure_ascii=False))
(root/'.nojekyll').write_text('')
print(f'Built {len(pages)} pages with local navigation and full-text guide search.')
